// Plasma effect
float SPEED = 0.25;
float FREQ = 1.0;
float AMP = 2.0;
float TIME_SHIFT = 0.5;
float ZOOM = 5.0;
int FBM_OCTAVES = 5;

// Glossy Plastic effect
float RADIANCE = 0.6;
float SHARPNESS = 0.8;
float GLOSS = 0.6;


float sinP(float x)
{
    return sin(x) * 0.5 + 0.5;
}

vec2 fbm(vec2 uv, float time, float f, float  a, float  t, float ff, float af, float tf)
{
    for(int s = 0; s < FBM_OCTAVES; ++s)
    {
        uv += vec2(sin(uv.y*f + time * t), cos(uv.x*f + time * t)) / a;
        f *= ff;
        t *= af;
        a *= tf;
    }

    return uv;
}


// Trick to achieve glossy effect from partial derivative (thx smart internet people)
vec4 glossy_plastic(vec4 color, float r, float s, float g)
{
    float shine = pow(abs(normalize(vec3(length(dFdx(color)), length(dFdy(color)), r / iResolution.y)).z), s) + g;
    return color * shine;
}
#define NUM_LAYERS 4.
#define TAU 6.28318
#define PI 3.141592
#define Velocity .025 //modified value to increse or decrease speed, negative value travel backwards
#define StarGlow 0.025
#define StarSize 02.
#define CanvasView 20.


float Star(vec2 uv, float flare){
    float d = length(uv);
  	float m = sin(StarGlow*1.2)/d;  
    float rays = max(0., .5-abs(uv.x*uv.y*1000.)); 
    m += (rays*flare)*2.;
    m *= smoothstep(1., .1, d);
    return m;
}

float Hash21(vec2 p){
    p = fract(p*vec2(123.34, 456.21));
    p += dot(p, p+45.32);
    return fract(p.x*p.y);
}


vec3 StarLayer(vec2 uv){
    vec3 col = vec3(0);
    vec2 gv = fract(uv);
    vec2 id = floor(uv);
    for(int y=-1;y<=1;y++){
        for(int x=-1; x<=1; x++){
            vec2 offs = vec2(x,y);
            float n = Hash21(id+offs);
            float size = fract(n);
            float star = Star(gv-offs-vec2(n, fract(n*34.))+.5, smoothstep(.1,.9,size)*.46);
            vec3 color = sin(vec3(.2,.3,.9)*fract(n*2345.2)*TAU)*.25+.75;
            color = color*vec3(.9,.59,.9+size);
            star *= sin(iTime*.6+n*TAU)*.5+.5;
            col += star*size*color;
        }
    }
    return col;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = (fragCoord.xy / iResolution.xy) - .5;
	float t = iTime * .1 + ((.25 + .05 * sin(iTime * .1))/(length(uv.xy) + .07)) * 2.2;
	float si = sin(t);
	float co = cos(t);
	mat2 ma = mat2(co, si, -si, co);

float time5 = (iTime+29.) * 60.0;

    float s2 = 0.0, v = 0.0;
    vec2 uv3 = (-iResolution.xy + 2.0 * fragCoord ) / iResolution.y;
	float t4 = time5*0.000;
vec4 o=fragColor;
vec2 F=fragCoord;
 vec2 R = iResolution.xy; 
    o-=o;
    for(float d,t = -iTime*.03, i = 0. ; i > -1.; i -= .06 )          	
    {   d = fract( i -3.*t );                                          	
        vec4 c = vec4( ( F - R *.5 ) / R.y *d ,i,0 ) * 28.;            	
        for (int j=0 ; j++ <27; )                                      	
            c.xzyw = abs( c / dot(c,c)                                 	
                    -vec4( 7.-.2*sin(t) , 6.3 , .7 , 1.-cos(t/.8))/7.);	
       o -= c * c.yzww  * d--*d  / vec4(3,5,1,1);                     
    }

	float si2 = sin(t4*1.5); // ...Squiffy rotation matrix!
	float co2 = cos(t4);
	uv *= mat2(co2, si2, -si2, co2);
	vec3 col4 = vec3(0.0);
	vec3 init = vec3(0.25, 0.25 + sin(time5 * 0.001) * .1, time5 * 0.0000);
	for (int r = 0; r < 100; r++) 
	{
		vec3 p = init + s2 * vec3(uv, 0.143);
		p.z = mod(p.z, 2.0);
		for (int i=0; i < 10; i++)	p = abs(p * 2.04) / dot(p, p) - 0.75;
		v += length(p * p) * smoothstep(0.0, 0.5, 0.9 - s2) * .002;
		// Get a purple and cyan effect by biasing the RGB in different ways...
		col4 +=  vec3(v * 0.8, 1.1 - s2 * 0.5, .7 + v * 0.5) * v * 0.013;
		s2 += .01;
	}
    float t3 = iTime*0.*Velocity; 
    vec3 col3 = vec3(0);  
    for(float i=0.; i<1.; i+=1./NUM_LAYERS){
        float depth = fract(i+t3);
        float scale = mix(CanvasView, .5, depth);
        float fade = depth*smoothstep(1.,.9,depth);
        col3 += StarLayer(uv*scale+i*453.2-iTime*.05)*fade;}   
	float v1, v2, v3;
	v1 = v2 = v3 = 0.0;
	 vec2 uv2 = fragCoord/iResolution.xy-0.5;
    uv2 -= vec2(0.5);
    uv2 *= ZOOM;

    float time = iTime * SPEED;

    uv2 = fbm(uv2,time, FREQ, AMP, TIME_SHIFT, 1.9, 1.1, 1.6);

    //vec3 col = vec3(step(uv.x*uv.x + uv.y*uv.y, 0.2*0.2));    

    float r = sinP(uv2.x+time);
    float g = sinP(uv2.y-time);
    float b = sinP(uv2.x*uv2.y + sinP(time*0.5));
    vec4 color = vec4(r,g,b, 1.0);

    color = glossy_plastic(color, RADIANCE, SHARPNESS, GLOSS);
	float s = 0.0;
	for (int i = 0; i < 120; i++)
	{
		vec3 p = s * vec3(uv, 0.0);

		p += vec3(.22, .3, s - 1.5 - sin(iTime * .13) * .1)+color.xyz+col3*col4+o.xyz;
		for (int i = 0; i < 8; i++)	p = abs(p) / dot(p,p) - 0.659;
		v1 += dot(p,p) * .0015 * (1.8 + sin(length(uv.xy * 13.0) + .5  - iTime * .2));
		v2 += dot(p,p) * .0013 * (1.5 + sin(length(uv.xy * 14.5) + 1.2 - iTime * .3));
		v3 += length(p.xy*10.) * .0003;
		s  += .035;
	}

	float len = length(uv);
	v1 *= smoothstep(.7, .0, len);
	v2 *= smoothstep(.5, .0, len);
	v3 *= smoothstep(.9, .0, len);

	vec3 col = vec3( v3 * (1.5 + sin(iTime * .2) * .4),
					(v1 + v3) * .3,
					 v2) + smoothstep(0.2, .0, len) * .85 + smoothstep(.0, .6, v3) * .3;

	fragColor=vec4(min(pow(abs(col)+color.xyz*2.*col3*2.+col4*0.4*o.xyz*7., vec3(1.2)), 1.0), 1.0);
}
